import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

public class TreesTour {
    static class Node {
        int key;
        Node left, right;
        Node(int key) { this.key = key; }
    }

    static Node insert(Node root, int key) {
        if (root == null) return new Node(key);
        if (key < root.key) root.left = insert(root.left, key);
        else if (key > root.key) root.right = insert(root.right, key);
        return root;                                   // duplicates are ignored
    }

    static void inorder(Node n, List<Integer> out) {
        if (n == null) return;
        inorder(n.left, out);
        out.add(n.key);
        inorder(n.right, out);
    }

    static int height(Node n) {                        // edges on the longest root-to-leaf path
        return n == null ? -1 : 1 + Math.max(height(n.left), height(n.right));
    }

    static List<List<Integer>> levels(Node root) {
        List<List<Integer>> out = new ArrayList<>();
        Deque<Node> queue = new ArrayDeque<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            List<Integer> level = new ArrayList<>();
            for (int i = queue.size(); i > 0; i--) {   // exactly one level per iteration
                Node n = queue.poll();
                level.add(n.key);
                if (n.left != null) queue.add(n.left);
                if (n.right != null) queue.add(n.right);
            }
            out.add(level);
        }
        return out;
    }

    public static void main(String[] args) {
        Node root = null;
        for (int key : new int[]{50, 30, 70, 20, 40, 60, 80, 35}) root = insert(root, key);
        List<Integer> sorted = new ArrayList<>();
        inorder(root, sorted);
        System.out.println("inorder (sorted): " + sorted);
        System.out.println("by level:         " + levels(root));
        System.out.println("height: " + height(root));

        Node chain = null;
        for (int key = 1; key <= 8; key++) chain = insert(chain, key);   // sorted input
        System.out.println("same count of keys inserted in sorted order -> height " + height(chain));
    }
}

