import java.util.ArrayDeque;
import java.util.Deque;

public class TreeTraversal {
    static class Node {
        char label;
        Node left, right;
        Node(char label, Node left, Node right) { this.label = label; this.left = left; this.right = right; }
    }

    static void preorder(Node n, StringBuilder out) {
        if (n == null) return;
        out.append(n.label).append(' ');      // node first
        preorder(n.left, out);
        preorder(n.right, out);
    }

    static void inorder(Node n, StringBuilder out) {
        if (n == null) return;
        inorder(n.left, out);
        out.append(n.label).append(' ');      // node in the middle
        inorder(n.right, out);
    }

    static void postorder(Node n, StringBuilder out) {
        if (n == null) return;
        postorder(n.left, out);
        postorder(n.right, out);
        out.append(n.label).append(' ');      // node last
    }

    static String inorderIterative(Node root) {
        StringBuilder out = new StringBuilder();
        Deque<Node> stack = new ArrayDeque<>();
        Node current = root;
        while (current != null || !stack.isEmpty()) {
            while (current != null) {         // go as far left as possible
                stack.push(current);
                current = current.left;
            }
            current = stack.pop();
            out.append(current.label).append(' ');
            current = current.right;          // then the right subtree
        }
        return out.toString().trim();
    }

    public static void main(String[] args) {
        //          F
        //        /   \
        //       B     G
        //      / \     \
        //     A   D     I
        //        / \   /
        //       C   E H
        Node root = new Node('F',
                new Node('B', new Node('A', null, null), new Node('D', new Node('C', null, null), new Node('E', null, null))),
                new Node('G', null, new Node('I', new Node('H', null, null), null)));
        StringBuilder pre = new StringBuilder(), in = new StringBuilder(), post = new StringBuilder();
        preorder(root, pre);
        inorder(root, in);
        postorder(root, post);
        System.out.println("preorder:  " + pre.toString().trim());
        System.out.println("inorder:   " + in.toString().trim());
        System.out.println("postorder: " + post.toString().trim());
        System.out.println("inorder with a stack: " + inorderIterative(root));

        System.out.println("level order:");
        Deque<Node> queue = new ArrayDeque<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            StringBuilder level = new StringBuilder();
            int size = queue.size();          // read once: this level only
            for (int i = 0; i < size; i++) {
                Node n = queue.poll();
                level.append(n.label).append(' ');
                if (n.left != null) queue.add(n.left);
                if (n.right != null) queue.add(n.right);
            }
            System.out.println("  " + level.toString().trim());
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class BinarySearchTree {
    static class Node {
        int key;
        Node left, right;
        Node(int key) { this.key = key; }
    }

    Node root;

    void insert(int key) { root = insert(root, key); }

    Node insert(Node n, int key) {
        if (n == null) return new Node(key);
        if (key < n.key) n.left = insert(n.left, key);
        else if (key > n.key) n.right = insert(n.right, key);
        return n;
    }

    boolean search(int key) {
        StringBuilder path = new StringBuilder();
        Node n = root;
        while (n != null) {
            path.append(n.key).append(' ');
            if (key == n.key) break;
            n = key < n.key ? n.left : n.right;      // discard the other subtree
        }
        System.out.println("search " + key + ": path " + path.toString().trim() + " -> " + (n != null ? "found" : "absent"));
        return n != null;
    }

    void delete(int key) { root = delete(root, key); }

    Node delete(Node n, int key) {
        if (n == null) return null;
        if (key < n.key) n.left = delete(n.left, key);
        else if (key > n.key) n.right = delete(n.right, key);
        else {
            if (n.left == null) return n.right;          // leaf or only a right child
            if (n.right == null) return n.left;          // only a left child
            Node successor = n.right;                    // two children: smallest key on the right
            while (successor.left != null) successor = successor.left;
            n.key = successor.key;
            n.right = delete(n.right, successor.key);    // remove the successor itself
        }
        return n;
    }

    List<Integer> inorder() {
        List<Integer> out = new ArrayList<>();
        walk(root, out);
        return out;
    }

    void walk(Node n, List<Integer> out) {
        if (n == null) return;
        walk(n.left, out);
        out.add(n.key);
        walk(n.right, out);
    }

    public static void main(String[] args) {
        BinarySearchTree bst = new BinarySearchTree();
        for (int key : new int[]{50, 30, 70, 20, 40, 60, 80, 35, 45, 65}) bst.insert(key);
        System.out.println("inorder: " + bst.inorder());
        bst.search(65);
        bst.search(55);
        bst.delete(45);
        System.out.println("delete 45 (leaf):         " + bst.inorder());
        bst.delete(60);
        System.out.println("delete 60 (one child):    " + bst.inorder());
        bst.delete(30);
        System.out.println("delete 30 (two children): " + bst.inorder() + ", 35 took its place: root.left = " + bst.root.left.key);
    }
}

