        if n is None:
            return None
        if key < n.key:
            n.left = self._delete(n.left, key)
        elif key > n.key:
            n.right = self._delete(n.right, key)
        else:
            if n.left is None:
                return n.right  # leaf or only a right child
            if n.right is None:
                return n.left   # only a left child
            successor = n.right  # two children: smallest key on the right
            while successor.left:
                successor = successor.left
            n.key = successor.key
            n.right = self._delete(n.right, successor.key)  # remove the successor itself
        return n

    def inorder(self):
        out = []

        def walk(n):
            if n:
                walk(n.left)
                out.append(n.key)
                walk(n.right)
        walk(self.root)
        return out


