import java.util.ArrayList;
import java.util.List;

public class PathProblems {
    static class Node {
        int val;
        Node left, right;
        Node(int val, Node left, Node right) { this.val = val; this.left = left; this.right = right; }
        Node(int val) { this(val, null, null); }
    }

    static void collect(Node n, List<Integer> path, int sum, List<String> out) {
        if (n == null) return;
        path.add(n.val);
        sum += n.val;
        if (n.left == null && n.right == null) out.add(path + " sum=" + sum);
        else {
            collect(n.left, path, sum, out);
            collect(n.right, path, sum, out);
        }
        path.remove(path.size() - 1);                 // backtrack before returning
    }

    static boolean hasPathSum(Node n, int remaining) {
        if (n == null) return false;
        remaining -= n.val;
        if (n.left == null && n.right == null) return remaining == 0;
        return hasPathSum(n.left, remaining) || hasPathSum(n.right, remaining);
    }

    static int diameter = 0;

    static int depth(Node n) {                        // height in edges, -1 for empty
        if (n == null) return -1;
        int left = depth(n.left), right = depth(n.right);
        diameter = Math.max(diameter, left + right + 2);   // longest path bending here
        return 1 + Math.max(left, right);
    }

    public static void main(String[] args) {
        //            5
        //          /   \
        //         4     8
        //        /     / \
        //      11    13   4
        //     /  \         \
        //    7    2         1
        Node root = new Node(5,
                new Node(4, new Node(11, new Node(7), new Node(2)), null),
                new Node(8, new Node(13), new Node(4, null, new Node(1))));
        List<String> paths = new ArrayList<>();
        collect(root, new ArrayList<>(), 0, paths);
        System.out.println("root-to-leaf paths:");
        for (String p : paths) System.out.println("  " + p);
        for (int target : new int[]{22, 26, 15}) {
            System.out.println("some path sums to " + target + "? " + hasPathSum(root, target));
        }
        depth(root);
        System.out.println("diameter: " + diameter + " edges");
    }
}

