import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class TreeConstruction {
    static class Node {
        int val;
        Node left, right;
        Node(int val) { this.val = val; }
    }

    static int[] preorder;
    static int preIndex = 0;
    static Map<Integer, Integer> inorderIndex = new HashMap<>();

    static Node build(int lo, int hi, int depth) {          // inorder[lo..hi]
        if (lo > hi) return null;
        int rootVal = preorder[preIndex++];                  // next preorder value is the root
        int mid = inorderIndex.get(rootVal);
        System.out.println("  ".repeat(depth) + "root " + rootVal + " owns inorder[" + lo + ".." + hi + "]");
        Node root = new Node(rootVal);
        root.left = build(lo, mid - 1, depth + 1);           // left first: preorder lists it first
        root.right = build(mid + 1, hi, depth + 1);
        return root;
    }

    static void postorder(Node n, List<Integer> out) {
        if (n == null) return;
        postorder(n.left, out);
        postorder(n.right, out);
        out.add(n.val);
    }

    public static void main(String[] args) {
        preorder = new int[]{3, 9, 20, 15, 7, 8};
        int[] inorder = {9, 3, 15, 20, 8, 7};
        for (int i = 0; i < inorder.length; i++) inorderIndex.put(inorder[i], i);
        Node root = build(0, inorder.length - 1, 0);

        List<Integer> post = new ArrayList<>();
        postorder(root, post);
        System.out.println("postorder of rebuilt tree: " + post);
        List<List<Integer>> levels = new ArrayList<>();
        Deque<Node> queue = new ArrayDeque<>(List.of(root));
        while (!queue.isEmpty()) {
            List<Integer> level = new ArrayList<>();
            for (int i = queue.size(); i > 0; i--) {
                Node n = queue.poll();
                level.add(n.val);
                if (n.left != null) queue.add(n.left);
                if (n.right != null) queue.add(n.right);
            }
            levels.add(level);
        }
        System.out.println("levels: " + levels);
    }
}

